import{_ as e,o,c as a,a2 as t}from"./chunks/framework.Di-jvWLj.js";const E=JSON.parse('{"title":"Tools & Tool Errors","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md","lastUpdated":1792229229000}'),n={name:"guide/tools.md"};function l(r,s,p,c,i,d){return o(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="tools-tool-errors" tabindex="-1">Tools &amp; Tool Errors <a class="header-anchor" href="#tools-tool-errors" aria-label="Permalink to &quot;Tools &amp; Tool Errors&quot;">​</a></h1><p>chamberu tools are AI SDK tools. Build them with <code>tool()</code> from <code>ai</code> and return them from the agent&#39;s <code>tools</code> factory. chamberu does not wrap or replace them, with one exception: <a href="/guide/effect-tools">effect tools</a> are wrapped so their side effect applies at most once.</p><h2 id="errors-go-back-to-the-model" tabindex="-1">Errors go back to the model <a class="header-anchor" href="#errors-go-back-to-the-model" aria-label="Permalink to &quot;Errors go back to the model&quot;">​</a></h2><p>When a tool throws, the AI SDK turns the error into a tool error result and the model sees it on its next call. It can retry, try something else or give up. The run does not fail, and the step is recorded as a <code>tool</code> step with <code>error: { code, message }</code>.</p><p>The <a href="/guide/budgets">step budget</a> caps retry loops: a model that keeps calling a failing tool runs out of steps and the run fails with <code>BudgetExceeded</code>.</p><h2 id="fataltoolerror-fails-the-run" tabindex="-1">FatalToolError fails the run <a class="header-anchor" href="#fataltoolerror-fails-the-run" aria-label="Permalink to &quot;FatalToolError fails the run&quot;">​</a></h2><p>Throw <code>FatalToolError</code> when continuing makes no sense: a missing credential, a forbidden target, a broken invariant.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> reader = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;reader&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Answer questions about the repository.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> ({</span></span>
<span class="line"><span style="color:#E6DFDE;">        readFile: tool({</span></span>
<span class="line"><span style="color:#E6DFDE;">            description: </span><span style="color:#E7C58C;">&#39;Reads a file of the repository.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            inputSchema: z.object({ path: z.string() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">            execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ path }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">                if</span><span style="color:#E6DFDE;"> (path.startsWith(</span><span style="color:#E7C58C;">&#39;/etc/&#39;</span><span style="color:#E6DFDE;">)) {</span></span>
<span class="line"><span style="color:#958A8B;">                    // fails the whole run with code &#39;FatalToolError&#39;</span></span>
<span class="line"><span style="color:#FF7B84;">                    throw</span><span style="color:#FF7B84;"> new</span><span style="color:#E6DFDE;"> FatalToolError(</span><span style="color:#E7C58C;">\`Refusing to read </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">path</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">.\`</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#E6DFDE;">                }</span></span>
<span class="line"><span style="color:#958A8B;">                // any other error goes back to the model as a tool error result</span></span>
<span class="line"><span style="color:#FF7B84;">                return</span><span style="color:#E6DFDE;"> readFile(path);</span></span>
<span class="line"><span style="color:#E6DFDE;">            },</span></span>
<span class="line"><span style="color:#E6DFDE;">        }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The run fails with <code>error.code</code> <code>FatalToolError</code>, or the code you pass as the second constructor argument (<code>new FatalToolError(message, &#39;MissingToken&#39;)</code>). The other tool calls of the same step still complete and are recorded before the run settles.</p><p>Infrastructure failures fail the run as well: a store write that throws, or an unknown agent.</p><h2 id="cancellation-inside-tools" tabindex="-1">Cancellation inside tools <a class="header-anchor" href="#cancellation-inside-tools" aria-label="Permalink to &quot;Cancellation inside tools&quot;">​</a></h2><p>Every tool factory gets <code>run.signal</code>. It aborts on cancel, drain, timeout and a lost lease. Pass it to <code>fetch</code>, child processes and other cancellable work so an aborted run stops quickly.</p><h2 id="tools-with-side-effects" tabindex="-1">Tools with side effects <a class="header-anchor" href="#tools-with-side-effects" aria-label="Permalink to &quot;Tools with side effects&quot;">​</a></h2><p>A recovered run repeats the step that was in progress when the process died. A plain tool that posts a comment would post it again. Use <a href="/guide/effect-tools"><code>defineEffectTool()</code></a> for every tool that changes something outside the run.</p>`,14)])])}const u=e(n,[["render",l]]);export{E as __pageData,u as default};
